EDITS = {'zoo_keeper/core/car_wear.py': [('lines 18-18', '  * ITS OWNER. Bumper stickers on the rear bumper (`sticker_quads`, the sheet `car_stickers`).\n', "  * ITS OWNER. Bumper stickers on the rear bumper (`sticker_quads`, the sheet `car_stickers`) -- on some cars:\n    a beater most often, a kept car seldom (`WEATHER`'s ``stuck``).\n"), ('lines 51-51', '#: is the chance of one filled dent in primer.\n', '#: is the chance of one filled dent in primer; ``stuck`` the chance that the stickers a car drew are on it at all.\n#:\n#: STICKERS ARE SOME CARS\' (1.120.1). 1.120.0 had no ``stuck``: a kept car drew none or one sticker and a driven\n#: car none to two, so in the factory\'s cold run 9365 seven of the street\'s eight parked modules carried a sticker --\n#: 27 of its 35 cars, where the walker asked for "some of the cars". With ``stuck`` the share is about three cars in\n#: eight (`sticker_share`); the draw comes after every other, so each car\'s rust, primer, peel and seed are what\n#: 1.120.0 drew, and only whether its stickers are on it moved.\n'), ('lines 54-56', '    "kept": {"sun": 0.10, "dust": 0.10, "rust": (0, 0), "primer": 0.00, "peel": (0, 0), "stickers": (0, 1)},\n    "driven": {"sun": 0.35, "dust": 0.35, "rust": (0, 2), "primer": 0.15, "peel": (0, 0), "stickers": (0, 2)},\n    "beater": {"sun": 0.80, "dust": 0.55, "rust": (2, 4), "primer": 0.60, "peel": (1, 3), "stickers": (1, 3)},\n', '    "kept": {"sun": 0.10, "dust": 0.10, "rust": (0, 0), "primer": 0.00, "peel": (0, 0), "stickers": (0, 1),\n             "stuck": 0.20},\n    "driven": {"sun": 0.35, "dust": 0.35, "rust": (0, 2), "primer": 0.15, "peel": (0, 0), "stickers": (0, 2),\n               "stuck": 0.60},\n    "beater": {"sun": 0.80, "dust": 0.55, "rust": (2, 4), "primer": 0.60, "peel": (1, 3), "stickers": (1, 3),\n               "stuck": 0.80},\n'), ('lines 177-178', '    seed = int(rng.random() * 1000003)\n    return {"history": name, "history_how": "asked" if asked in WEATHER else "drawn",\n', '    seed = int(rng.random() * 1000003)\n    # LAST, so it moves nothing drawn before it (1.120.1): are the stickers it drew on it at all\n    if rng.random() >= w["stuck"]:\n        stickers = []\n    return {"history": name, "history_how": "asked" if asked in WEATHER else "drawn",\n'), ('lines 180-181', '            "stickers": tuple(stickers), "wear_seed": seed}\n\n', '            "stickers": tuple(stickers), "wear_seed": seed}\n\n\ndef sticker_share():\n    """The share of a street\'s cars that carry a sticker, from the tables: each history\'s weight times the chance it\n    drew at least one, times `stuck`."""\n    out = 0.0\n    for name, weight in HISTORIES:\n        w = WEATHER[name]\n        lo, hi = w["stickers"]\n        drew = (hi - max(lo, 1) + 1) / float(hi - lo + 1) if hi >= 1 else 0.0\n        out += weight * drew * w["stuck"]\n    return out\n\n')], 'tests/test_car_wear.py': [('lines 70-71', '\ndef test_an_asked_history_wins_and_a_drawn_one_says_so():\n', '\n#: 1.120.0\'s histories for the same four stems, every draw (history, rust, primer, peel, stickers, seed) --\n#: literals, read off 1.120.0.\nHISTORY_1120 = (\n    ("prop_simple_car_delco_1997_01_w175_d430_h145", "beater", (("rear_arch", 1), ("front_arch", -1),\n                                                                ("rear_arch", -1)), True, 3, (4, 5, 8), 46222),\n    ("prop_simple_car_delco_1997_02_w175_d480_h142", "kept", (), False, 0, (5,), 331612),\n    ("prop_simple_car_delco_1997_01_w160_d380_h140", "driven", (("rear_arch", 1),), False, 0, (0,), 126983),\n    ("prop_simple_car_delco_1997_02_w180_d470_h173", "driven", (), False, 0, (11,), 512975),\n)\n\n\ndef test_whether_its_stickers_are_on_moves_nothing_else_1120_drew():\n    """1.120.1 draws `stuck` LAST: every car keeps 1.120.0\'s history, rust, primer, peel and seed, and its stickers\n    are the ones it drew or none."""\n    for stem, name, rust, primer, peel, stickers, seed in HISTORY_1120:\n        h = car_wear.resolve({}, _streams(stem))\n        assert (h["history"], h["rust"], h["primer"], h["peel"], h["wear_seed"]) == (name, rust, primer, peel, seed)\n        assert h["stickers"] in (stickers, ()), (stem, h["stickers"])\n\n\ndef test_stickers_are_some_cars_not_most():\n    """The walker: "some of the cars". 1.120.0 put a sticker on 27 of cold run 9365\'s 35 parked cars. Over 3,000\n    stems the share is `sticker_share` within three points, and that is under half."""\n    n = sum(1 for k in range(3000) if car_wear.resolve({}, _streams("st_%d" % k))["stickers"])\n    assert n / 3000.0 < 0.45, n\n    assert abs(n / 3000.0 - car_wear.sticker_share()) < 0.03, (n, car_wear.sticker_share())\n\n\ndef test_an_asked_history_wins_and_a_drawn_one_says_so():\n'), ('lines 84-84', '            assert w["stickers"][0] <= len(h["stickers"]) <= w["stickers"][1]\n', '            assert len(h["stickers"]) == 0 or w["stickers"][0] <= len(h["stickers"]) <= w["stickers"][1]\n')], 'tests/test_car_forms.py': [('lines 45-45', "#: six SUV beaters over the genome's 3,400 -- raised to 3,500 for it:\n", "#: six SUV beaters over the genome's 3,400 -- raised to 3,500 for it. Its\n#: maxima: sedan 3,192, hatchback 3,020, SUV 3,436, coupe 3,128.\n#:\n#: AND AGAIN for 1.120.1, whose stickers are some cars' (`car_wear`'s\n#: `stuck`): the same 646, 0 pairs, every check passing:\n"), ('lines 47-48', '            "tris_max": {"sedan": 3192, "hatchback": 3020, "suv": 3436,\n                         "coupe": 3128}}\n', '            "tris_max": {"sedan": 3188, "hatchback": 3020, "suv": 3430,\n                         "coupe": 3122}}\n')]}
NEW_FILES = {}
CHANGELOG = '## [1.120.1] - stickers are some cars\', not most\n\n**Measured in a package, the factory\'s cold run 9365** (bank_block_001, seed 9082, Zoo 1.120.0): seven of the\nstreet\'s eight parked modules carried a sticker -- 27 of its 35 cars -- where the walker asked for "some of the\ncars". 1.120.0 drew a kept car none or one sticker and a driven car none to two, so over 3,000 stems 2,026 cars in\n3,000 carried one (67.5 %). The cost is the sticker\'s material, one submission a stickered car: the package\'s parked\ncars were 140 surfaces at 1.119.0 and 167 at 1.120.0, every one of the 27 more a sticker sheet.\n\n- **`WEATHER`\'s ``stuck``**: the chance that the stickers a car drew are on it at all -- kept 0.20, driven 0.60,\n  beater 0.80 -- so about three cars in eight carry one (`car_wear.sticker_share`, 0.375; measured over 3,000 stems\n  within three points). The draw comes LAST in the history\'s stream: every car keeps 1.120.0\'s history, rust,\n  primer, peel and seed, and its stickers are the ones it drew or none (four of Lot\'s parked modules, read off\n  1.120.0 as literals). On bank_block_001\'s street at seed 9082 that is two of the eight modules -- the silver beater\n  compact and one driven SUV -- seven of its 35 cars.\n- **The matrix again** (the factory\'s `patches/zoo_car_wear/car_matrix.py`): 646 builds, 0 SAME and 0 OPP pairs, every\n  check passing, tris max sedan 3,188, hatchback 3,020, SUV 3,430, coupe 3,122 (`test_car_forms.py`\'s MEASURED).\n\n### Tests\n- `test_car_wear.py`: two more (15) -- whether a car\'s stickers are on moves nothing else 1.120.0 drew, and stickers\n  are under half the street\'s cars and the tables\' share within three points; the second fails on 1.120.0 (2,026 of\n  3,000).\n\n'
OLD_VERSION, NEW_VERSION = '1.120.0', '1.120.1'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
